import { Ionicons } from "@expo/vector-icons";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useRouter } from "expo-router";
import { useEffect, useState } from "react";
import { ActivityIndicator, Image, Pressable, StyleSheet, Text, TextInput, View } from "react-native";
import { ModuleCard } from "../../ui/ModuleCard";
import { Screen } from "../../ui/Screen";
import { colors, radius, spacing } from "../../ui/tokens";
import { firebaseAuth } from "../auth/firebase";
import { createVendorProduct, getCategories, getVendorProducts, replaceVendorProductMedia, replaceVendorProductVariants, updateVendorProduct } from "../catalog/catalog.api";
import { pickAndUploadImage } from "../media/media.api";
import { ProductCategorySelect } from "./components/ProductCategorySelect";
import { getVendorWorkspace } from "./vendor.api";

type VariantDraft = { id?: string; color: string; size: string; sku: string; title: string; price: string; compareAt: string; stock: string; active: boolean };
type MediaDraft = { id?: string; uploadId?: string; uri: string; altText: string; variantSku: string };
const initial = { name: "", brand: "", categoryId: "", description: "", colors: "", sizes: "" };
const emptyVariant = (): VariantDraft => ({ color: "", size: "", sku: "", title: "Default", price: "", compareAt: "", stock: "0", active: true });

export function VendorProductFormScreen({ id }: { id?: string }) {
  const editing = Boolean(id);
  const router = useRouter();
  const user = firebaseAuth?.currentUser ?? null;
  const cache = useQueryClient();
  const products = useQuery({ queryKey: ["vendor", "products"], queryFn: () => getVendorProducts(user!), enabled: Boolean(user && editing) });
  const categories = useQuery({ queryKey: ["catalog", "categories"], queryFn: getCategories });
  const workspace = useQuery({ queryKey: ["vendor", "workspace"], queryFn: () => getVendorWorkspace(user!), enabled: Boolean(user && !editing) });
  const product = products.data?.find((item) => item.id === id);
  const [form, setForm] = useState(initial);
  const [variants, setVariants] = useState<VariantDraft[]>([emptyVariant()]);
  const [media, setMedia] = useState<MediaDraft[]>([]);
  const [uploading, setUploading] = useState(false);
  const [uploadError, setUploadError] = useState("");

  useEffect(() => {
    if (!product) return;
    const productVariants = product.variants.map((variant) => ({ id: variant.id, color: textAttribute(variant.attributes?.color), size: textAttribute(variant.attributes?.size), sku: variant.sku, title: variant.title, price: decimal(variant.price.amountMinor), compareAt: variant.compareAtPrice ? decimal(variant.compareAtPrice.amountMinor) : "", stock: String(variant.availableQuantity), active: variant.active }));
    setForm({ name: product.name, brand: product.brand ?? "", categoryId: product.categoryId, description: product.description ?? "", colors: unique(productVariants.map((item) => item.color)).join(", "), sizes: unique(productVariants.map((item) => item.size)).join(", ") });
    setVariants(productVariants.length ? productVariants : [emptyVariant()]);
    setMedia(product.media.map((item) => ({ id: item.id, uri: item.url, altText: item.altText ?? "", variantSku: product.variants.find((variant) => variant.id === item.variantId)?.sku ?? "" })));
  }, [product]);

  const validVariants = variants.every((variant) => variant.sku.trim().length >= 3 && variant.title.trim().length > 0 && Number(variant.price) > 0 && Number(variant.stock) >= 0);
  const valid = form.name.trim().length >= 3 && Boolean(form.categoryId) && variants.length > 0 && validVariants;
  const save = useMutation({ mutationFn: async () => {
    const payload = variants.map((variant) => ({ ...(variant.id ? { id: variant.id } : {}), sku: variant.sku.trim().toUpperCase(), title: variant.title.trim(), attributes: { ...(variant.color ? { color: variant.color } : {}), ...(variant.size ? { size: variant.size } : {}) }, priceMinor: minor(variant.price), compareAtMinor: variant.compareAt ? minor(variant.compareAt) : null, currency: "BDT", onHand: Number(variant.stock), active: variant.active }));
    let current = editing
      ? await updateVendorProduct(user!, id!, { version: product!.version, name: form.name, brand: form.brand.trim() || null, categoryId: form.categoryId, description: form.description.trim() || null })
      : await createVendorProduct(user!, { shopId: workspace.data!.shops[0]!.id, categoryId: form.categoryId, name: form.name, slug: slug(form.name), brand: form.brand.trim() || null, description: form.description.trim() || null, variants: payload.map(({ id: _id, active: _active, ...variant }) => variant) });
    if (editing) current = await replaceVendorProductVariants(user!, current.id, { version: current.version, variants: payload });
    if (editing || media.length) current = await replaceVendorProductMedia(user!, current.id, { version: current.version, items: media.map((item, index) => ({ ...(item.id ? { id: item.id } : { uploadId: item.uploadId! }), variantId: current.variants.find((variant) => variant.sku === item.variantSku)?.id ?? null, altText: item.altText.trim() || null, displayOrder: index })) });
    return current;
  }, onSuccess: async (saved) => { await cache.invalidateQueries({ queryKey: ["vendor", "products"] }); router.replace(`/vendor/products/${saved.id}` as never); } });

  const uploadImage = async () => {
    if (media.length >= 12) return;
    setUploadError(""); setUploading(true);
    try { const result = await pickAndUploadImage(user!, "product"); if (result) setMedia((items) => [...items, { uploadId: result.id, uri: result.localUri || result.publicUrl || "", altText: form.name, variantSku: "" }]); }
    catch (error) { setUploadError(error instanceof Error ? error.message : "Image upload failed"); }
    finally { setUploading(false); }
  };
  const generateVariants = () => {
    const colors = values(form.colors); const sizes = values(form.sizes);
    if (!colors.length && !sizes.length) return;
    const combinations = (colors.length ? colors : [""]).flatMap((color) => (sizes.length ? sizes : [""]).map((size) => ({ color, size })));
    setVariants(combinations.map(({ color, size }, index) => { const existing = variants.find((item) => item.color.toLowerCase() === color.toLowerCase() && item.size.toLowerCase() === size.toLowerCase()); return existing ?? { ...emptyVariant(), color, size, title: [color, size].filter(Boolean).join(" / ") || "Default", sku: makeSku(form.name, color, size, index) }; }));
  };
  const updateVariant = (index: number, change: Partial<VariantDraft>) => setVariants((items) => items.map((item, itemIndex) => itemIndex === index ? { ...item, ...change } : item));

  if (editing && products.isLoading) return <Screen title="Loading product"><ActivityIndicator color={colors.primary} /></Screen>;
  if (editing && !product) return <Screen title="Product unavailable" description="This product could not be found in your seller catalog."><Pressable onPress={() => router.replace("/vendor/products")} style={styles.primary}><Text style={styles.primaryText}>Back to products</Text></Pressable></Screen>;
  return <Screen eyebrow="SELLER CATALOG" title={editing ? "Edit product" : "Add a product"} description="Build a complete listing with gallery images, variants, pricing and stock.">
    <View style={styles.steps}><Step active label="Information" number="1" /><View style={styles.rail} /><Step active label="Media" number="2" /><View style={styles.rail} /><Step active label="Variants" number="3" /></View>
    <ModuleCard title="Product information" meta="Use a clear customer-facing name and accurate category."><Field label="Product name *" onChangeText={(name) => setForm({ ...form, name })} placeholder="Enter product name" value={form.name} /><Field label="Brand" onChangeText={(brand) => setForm({ ...form, brand })} placeholder="Brand or manufacturer" value={form.brand} /><ProductCategorySelect categories={categories.data ?? []} onChange={(categoryId) => setForm({ ...form, categoryId })} value={form.categoryId} /><Field label="Description" multiline onChangeText={(description) => setForm({ ...form, description })} placeholder="Describe features, materials, size and usage" value={form.description} /></ModuleCard>
    <ModuleCard title="Product media" meta={`${media.length}/12 images · JPG, PNG or WebP`}><View style={styles.gallery}>{media.map((item, index) => <View key={item.id ?? item.uploadId} style={styles.mediaCard}>{item.uri ? <Image source={{ uri: item.uri }} style={styles.mediaImage} /> : <View style={styles.mediaImageFallback}><Ionicons color={colors.muted} name="image-outline" size={28} /></View>}<Pressable accessibilityLabel="Remove image" onPress={() => setMedia((items) => items.filter((_, itemIndex) => itemIndex !== index))} style={styles.removeMedia}><Ionicons color={colors.surface} name="close" size={16} /></Pressable><TextInput onChangeText={(altText) => setMedia((items) => items.map((entry, itemIndex) => itemIndex === index ? { ...entry, altText } : entry))} placeholder="Image alt text" placeholderTextColor={colors.muted} style={styles.altInput} value={item.altText} /><View style={styles.mediaVariants}><Pressable onPress={() => setMedia((items) => items.map((entry, itemIndex) => itemIndex === index ? { ...entry, variantSku: "" } : entry))} style={[styles.mediaVariant, !item.variantSku && styles.mediaVariantActive]}><Text style={[styles.mediaVariantText, !item.variantSku && styles.mediaVariantTextActive]}>All</Text></Pressable>{variants.slice(0, 4).map((variant) => <Pressable key={variant.sku || variant.title} onPress={() => setMedia((items) => items.map((entry, itemIndex) => itemIndex === index ? { ...entry, variantSku: variant.sku } : entry))} style={[styles.mediaVariant, item.variantSku === variant.sku && styles.mediaVariantActive]}><Text numberOfLines={1} style={[styles.mediaVariantText, item.variantSku === variant.sku && styles.mediaVariantTextActive]}>{variant.sku || variant.title}</Text></Pressable>)}</View><Text style={styles.mediaOrder}>IMAGE {index + 1}{index === 0 ? " · COVER" : ""}</Text></View>)}{media.length < 12 ? <Pressable disabled={uploading} onPress={() => void uploadImage()} style={styles.addMedia}>{uploading ? <ActivityIndicator color={colors.primary} /> : <><Ionicons color={colors.primary} name="cloud-upload-outline" size={27} /><Text style={styles.addMediaTitle}>Add image</Text><Text style={styles.addMediaMeta}>Up to 10 MB</Text></>}</Pressable> : null}</View>{uploadError ? <Text style={styles.error}>{uploadError}</Text> : null}</ModuleCard>
    <ModuleCard title="Variant generator" meta="Enter comma-separated colors and sizes, then generate the matrix."><View style={styles.row}><Field label="Colors" onChangeText={(colorsValue) => setForm({ ...form, colors: colorsValue })} placeholder="Black, Blue, Red" value={form.colors} /><Field label="Sizes" onChangeText={(sizes) => setForm({ ...form, sizes })} placeholder="S, M, L, XL" value={form.sizes} /></View><Pressable onPress={generateVariants} style={styles.outline}><Ionicons color={colors.primary} name="git-branch-outline" size={18} /><Text style={styles.outlineText}>Generate color and size variants</Text></Pressable></ModuleCard>
    <ModuleCard title={`Variant matrix · ${variants.length}`} meta={`${variants.reduce((sum, variant) => sum + (Number(variant.stock) || 0), 0)} total opening stock`}><View style={styles.variantList}>{variants.map((variant, index) => <View key={variant.id ?? `${index}-${variant.color}-${variant.size}`} style={styles.variantCard}><View style={styles.variantHeader}><View style={styles.variantNumber}><Text style={styles.variantNumberText}>{index + 1}</Text></View><Text style={styles.variantHeading}>{variant.title || `Variant ${index + 1}`}</Text><Pressable disabled={variants.length === 1} onPress={() => setVariants((items) => items.filter((_, itemIndex) => itemIndex !== index))}><Ionicons color={variants.length === 1 ? colors.border : colors.danger} name="trash-outline" size={19} /></Pressable></View><View style={styles.row}><Field label="Color" onChangeText={(color) => updateVariant(index, { color, title: [color, variant.size].filter(Boolean).join(" / ") || "Default" })} value={variant.color} /><Field label="Size" onChangeText={(size) => updateVariant(index, { size, title: [variant.color, size].filter(Boolean).join(" / ") || "Default" })} value={variant.size} /><Field label="SKU *" onChangeText={(sku) => updateVariant(index, { sku: sku.toUpperCase() })} value={variant.sku} /></View><View style={styles.row}><Field keyboardType="decimal-pad" label="Price *" onChangeText={(price) => updateVariant(index, { price })} value={variant.price} /><Field keyboardType="decimal-pad" label="Compare at" onChangeText={(compareAt) => updateVariant(index, { compareAt })} value={variant.compareAt} /><Field keyboardType="numeric" label="Stock *" onChangeText={(stock) => updateVariant(index, { stock })} value={variant.stock} /></View><Pressable onPress={() => updateVariant(index, { active: !variant.active })} style={styles.activeRow}><Ionicons color={variant.active ? colors.success : colors.muted} name={variant.active ? "checkbox" : "square-outline"} size={20} /><Text style={styles.activeText}>Variant is active and sellable</Text></Pressable></View>)}</View><Pressable onPress={() => setVariants((items) => [...items, emptyVariant()])} style={styles.outline}><Ionicons color={colors.primary} name="add" size={18} /><Text style={styles.outlineText}>Add another variant</Text></Pressable></ModuleCard>
    {save.error ? <Text style={styles.error}>{save.error.message}</Text> : null}<View style={styles.footer}><Pressable onPress={() => router.back()} style={styles.cancel}><Text style={styles.cancelText}>Cancel</Text></Pressable><Pressable disabled={!valid || save.isPending || uploading} onPress={() => save.mutate()} style={[styles.primary, (!valid || save.isPending || uploading) && styles.disabled]}>{save.isPending ? <ActivityIndicator color={colors.surface} /> : <Text style={styles.primaryText}>{editing ? "Save product and variants" : "Create draft product"}</Text>}</Pressable></View>
  </Screen>;
}

function Field(props: React.ComponentProps<typeof TextInput> & { label: string }) { const { label, ...input } = props; return <View style={styles.field}><Text style={styles.label}>{label}</Text><TextInput placeholderTextColor={colors.muted} style={[styles.input, input.multiline && styles.multiline]} {...input} /></View>; }
function Step({ active, label, number }: { active?: boolean; label: string; number: string }) { return <View style={styles.step}><View style={[styles.stepNumber, active && styles.stepActive]}><Text style={[styles.stepNumberText, active && styles.stepNumberTextActive]}>{number}</Text></View><Text style={styles.stepLabel}>{label}</Text></View>; }
function values(value: string) { return unique(value.split(",").map((item) => item.trim()).filter(Boolean)); }
function unique(valuesInput: string[]) { return [...new Set(valuesInput.filter(Boolean))]; }
function slug(value: string) { return value.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, ""); }
function minor(value: string) { return String(Math.round(Number(value) * 100)); }
function decimal(value: string) { return String(Number(value) / 100); }
function textAttribute(value: unknown) { return typeof value === "string" ? value : ""; }
function makeSku(name: string, color: string, size: string, index: number) { const part = (value: string, fallback: string) => value.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 6) || fallback; return `${part(name, "ITEM")}-${part(color, "CLR")}-${part(size, String(index + 1))}`; }
const styles = StyleSheet.create({ steps: { alignItems: "center", alignSelf: "center", flexDirection: "row", maxWidth: 520, width: "100%" }, step: { alignItems: "center", gap: 5 }, stepNumber: { alignItems: "center", backgroundColor: "#e2e8f0", borderRadius: radius.pill, height: 30, justifyContent: "center", width: 30 }, stepActive: { backgroundColor: colors.primary }, stepNumberText: { color: colors.muted, fontWeight: "900" }, stepNumberTextActive: { color: colors.surface }, stepLabel: { color: colors.muted, fontSize: 9, fontWeight: "800" }, rail: { backgroundColor: colors.primary, flex: 1, height: 2, marginBottom: 19 }, field: { flex: 1, gap: 6, minWidth: 170 }, label: { color: colors.text, fontSize: 12, fontWeight: "800" }, input: { backgroundColor: "#f8fafc", borderColor: colors.border, borderRadius: radius.md, borderWidth: 1, color: colors.text, minHeight: 48, paddingHorizontal: 13 }, multiline: { minHeight: 130, paddingVertical: 12, textAlignVertical: "top" }, row: { flexDirection: "row", flexWrap: "wrap", gap: spacing.md }, gallery: { flexDirection: "row", flexWrap: "wrap", gap: spacing.md }, mediaCard: { backgroundColor: "#f8fafc", borderColor: colors.border, borderRadius: radius.lg, borderWidth: 1, overflow: "hidden", position: "relative", width: 180 }, mediaImage: { height: 145, width: "100%" }, mediaImageFallback: { alignItems: "center", height: 145, justifyContent: "center" }, removeMedia: { alignItems: "center", backgroundColor: "rgba(15,23,42,.78)", borderRadius: radius.pill, height: 28, justifyContent: "center", position: "absolute", right: 7, top: 7, width: 28 }, altInput: { borderTopColor: colors.border, borderTopWidth: 1, color: colors.text, fontSize: 10, minHeight: 38, paddingHorizontal: 8 }, mediaVariants: { flexDirection: "row", flexWrap: "wrap", gap: 3, paddingHorizontal: 6 }, mediaVariant: { borderColor: colors.border, borderRadius: radius.pill, borderWidth: 1, maxWidth: 76, paddingHorizontal: 6, paddingVertical: 4 }, mediaVariantActive: { backgroundColor: colors.primary, borderColor: colors.primary }, mediaVariantText: { color: colors.muted, fontSize: 7, fontWeight: "800" }, mediaVariantTextActive: { color: colors.surface }, mediaOrder: { color: colors.muted, fontSize: 8, fontWeight: "900", padding: 8 }, addMedia: { alignItems: "center", borderColor: colors.primary, borderRadius: radius.lg, borderStyle: "dashed", borderWidth: 1, gap: 5, height: 220, justifyContent: "center", width: 180 }, addMediaTitle: { color: colors.primary, fontWeight: "900" }, addMediaMeta: { color: colors.muted, fontSize: 9 }, outline: { alignItems: "center", borderColor: colors.primary, borderRadius: radius.md, borderWidth: 1, flexDirection: "row", gap: 7, justifyContent: "center", minHeight: 46 }, outlineText: { color: colors.primary, fontWeight: "900" }, variantList: { gap: spacing.md }, variantCard: { backgroundColor: "#f8fafc", borderColor: colors.border, borderRadius: radius.lg, borderWidth: 1, gap: spacing.md, padding: spacing.md }, variantHeader: { alignItems: "center", flexDirection: "row", gap: spacing.sm }, variantNumber: { alignItems: "center", backgroundColor: colors.primary, borderRadius: radius.pill, height: 27, justifyContent: "center", width: 27 }, variantNumberText: { color: colors.surface, fontSize: 10, fontWeight: "900" }, variantHeading: { color: colors.text, flex: 1, fontWeight: "900" }, activeRow: { alignItems: "center", flexDirection: "row", gap: 7 }, activeText: { color: colors.text, fontSize: 11, fontWeight: "800" }, footer: { flexDirection: "row", flexWrap: "wrap", gap: spacing.sm, justifyContent: "flex-end" }, cancel: { alignItems: "center", borderColor: colors.border, borderRadius: radius.md, borderWidth: 1, justifyContent: "center", minHeight: 48, minWidth: 120 }, cancelText: { color: colors.text, fontWeight: "900" }, primary: { alignItems: "center", backgroundColor: colors.primary, borderRadius: radius.md, justifyContent: "center", minHeight: 48, minWidth: 210, paddingHorizontal: spacing.lg }, primaryText: { color: colors.surface, fontWeight: "900" }, disabled: { opacity: .45 }, error: { color: colors.danger } });
